// SipHash-inspired keyed hash for session routing behind reverse proxy
// Proxy forwards X-Forwarded-Session header for sticky sessions
struct SessionHash {
    size_t seed_;
    SessionHash() {
        std::random_device rd;
        seed_ = rd();
    }
    size_t operator()(const std::string& key) const {
        // Use std::hash with per-instance randomized seed
        size_t h = std::hash<std::string>{}(key);
        h ^= seed_ + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

struct WebSocketFrame {
    uint8_t opcode;
    std::string payload;
    std::string session_id;
    std::string origin_ip;
};

// Escape a string so it is safe to embed inside a JSON string literal.
static std::string json_escape(const std::string& in) {
    std::string out;
    out.reserve(in.size() + 8);
    for (unsigned char c : in) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    char buf[8];
                    std::snprintf(buf, sizeof(buf), "\\u%04x", c);
                    out += buf;
                } else {
                    out += static_cast<char>(c);
                }
        }
    }
    return out;
}

class RateLimiter {
private:
    std::unordered_map<std::string, std::vector<std::chrono::steady_clock::time_point>> request_log_;
    std::mutex mtx_;
    static constexpr int MAX_REQUESTS_PER_SECOND = 100;
public:
    bool allow(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        auto& timestamps = request_log_[ip];
        // Prune old entries
        timestamps.erase(
            std::remove_if(timestamps.begin(), timestamps.end(),
                [&now](const auto& t) {
                    return std::chrono::duration_cast<std::chrono::seconds>(now - t).count() > 1;
                }),
            timestamps.end());
        if (timestamps.size() >= MAX_REQUESTS_PER_SECOND) {
            return false;
        }
        timestamps.push_back(now);
        return true;
    }
};

class SessionStore {
private:
    // Session data indexed by session ID from proxy header
    std::unordered_map<std::string, std::string, SessionHash> sessions_;
    std::mutex mtx_;
    static constexpr size_t MAX_SESSIONS = 100000;
public:
    bool store(const std::string& session_id, const std::string& data) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (sessions_.size() >= MAX_SESSIONS) {
            return false;
        }
        sessions_[session_id] = data;
        return true;
    }

    std::string retrieve(const std::string& session_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(session_id);
        if (it != sessions_.end()) {
            return it->second;
        }
        return "";
    }

    size_t count() const { return sessions_.size(); }
};

class WebSocketHandler {
private:
    SessionStore session_store_;
    RateLimiter rate_limiter_;

    std::string extract_proxy_header(const std::string& raw_headers, const std::string& header_name) {
        std::istringstream stream(raw_headers);
        std::string line;
        while (std::getline(stream, line)) {
            if (line.find(header_name + ":") == 0) {
                std::string value = line.substr(header_name.size() + 1);
                // Trim whitespace
                value.erase(0, value.find_first_not_of(" \t\r\n"));
                value.erase(value.find_last_not_of(" \t\r\n") + 1);
                return value;
            }
        }
        return "";
    }

    bool validate_session_id(const std::string& sid) {
        if (sid.empty() || sid.size() > 128) return false;
        // Allow alphanumeric, hyphens, underscores
        for (char c : sid) {
            if (!std::isalnum(static_cast<unsigned char>(c)) && c != '-' && c != '_') {
                return false;
            }
        }
        return true;
    }

public:
    std::string handle_frame(const WebSocketFrame& frame, const std::string& upgrade_headers) {
        // Rate limit by origin IP (set by reverse proxy)
        if (!rate_limiter_.allow(frame.origin_ip)) {
            return "{\"error\": \"rate_limited\"}";
        }

        // Extract session from proxy-injected header
        std::string session_id = extract_proxy_header(upgrade_headers, "X-Forwarded-Session");
        if (session_id.empty()) {
            session_id = frame.session_id;
        }

        if (!validate_session_id(session_id)) {
            return "{\"error\": \"invalid_session\"}";
        }

        // Process based on opcode
        switch (frame.opcode) {
            case 0x1: { // Text frame - store session data
                if (frame.payload.size() > 4096) {
                    return "{\"error\": \"payload_too_large\"}";
                }
                if (session_store_.store(session_id, frame.payload)) {
                    return "{\"status\": \"stored\"}";
                }
                return "{\"error\": \"store_full\"}";
            }
            case 0x2: { // Binary frame - retrieve session
                std::string data = session_store_.retrieve(session_id);
                // Escape stored data before embedding into JSON to prevent JSON injection.
                return "{\"data\": \"" + json_escape(data) + "\"}";
            }
            case 0x9: { // Ping
                return "{\"pong\": true}";
            }
            default:
                return "{\"error\": \"unsupported_opcode\"}";
        }
    }
};

// Simulated server loop
int main() {
    WebSocketHandler handler;

    // Simulate incoming frames from reverse proxy
    std::string headers = "X-Forwarded-For: 192.168.1.100\r\nX-Forwarded-Session: user-abc-123\r\n";

    WebSocketFrame frame;
    frame.opcode = 0x1;
    frame.payload = "{\"msg\": \"hello\"}";
    frame.session_id = "fallback-session";
    frame.origin_ip = "192.168.1.100";

    std::string response = handler.handle_frame(frame, headers);
    std::cout << "Response: " << response << std::endl;

    return 0;
}
